package com.yuewei.plm.module.partner;

import java.util.*;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.annotation.Isolation;
import static com.yuewei.plm.module.partner.PartnerValues.*;

/** One SY type, many immutable SP receipt ledgers. There is no second stock table. */
@Service @RequiredArgsConstructor
public class SampleIdentityRegistry {
 private final PartnerStore store;
 private void read(){store.access.requireDomesticView();store.access.requirePermission("partner:view");}
 private void write(){read();store.access.requirePermission("samples:write");}
 private String visible(String alias){
  long user=store.access.actorId();String direct=store.access.visibleSqlClause("partner",alias+".record_id"),batch=store.access.visibleSqlClause("partner","ib.record_id");
  String project=store.access.hasPermission("product:view")?"(("+alias+".source_project_id is not null and "+store.access.visibleSqlClause("product",alias+".source_project_id")+") or exists(select 1 from plm_product source_model where source_model.deleted_flag=0 and source_model.product_id::text="+alias+".data->>'modelProductId' and ("+store.access.visibleSqlClause("product","source_model.product_id")+")))":"false";
  String product="exists(select 1 from plm_partner_record source_product where source_product.kind='product' and source_product.deleted_flag=0 and source_product.record_id::text="+alias+".data->>'productId' and ("+store.access.visibleSqlClause("partner","source_product.record_id")+"))";
  return "("+alias+".owner_user_id="+user+" or ("+direct+") or exists(select 1 from plm_partner_record ib where ib.kind='sample' and ib.deleted_flag=0 and ib.sample_identity_id="+alias+".record_id and ("+batch+")) or exists(select 1 from plm_partner_record redirected_batch where redirected_batch.kind='sample' and redirected_batch.deleted_flag=0 and redirected_batch.sample_identity_id::text="+alias+".data->>'redirectIdentityId' and ("+store.access.visibleSqlClause("partner","redirected_batch.record_id")+")) or "+project+" or "+product+" or exists(select 1 from plm_partner_catalog_style_source cs join plm_partner_record origin on origin.record_id=cs.record_id where cs.style_id::text="+alias+".data->>'catalogStyleId' and origin.deleted_flag=0 and ("+store.access.visibleSqlClause("partner","origin.record_id")+")))";
 }
 private Map<String,Object> header(Map<String,Object> row){var d=decode(store.json,row.get("data"));d.put("id",row.get("record_id"));d.put("code",row.get("code"));d.put("sampleIdentityId",row.get("record_id"));d.put("sampleCode",row.get("code"));d.put("name",row.get("name"));d.put("status",row.get("status"));d.put("version",row.get("version"));d.put("supplierCode",text(d.get("supplierCode")));d.put("supplierName",supplierName(d));return d;}
 public Map<String,Object> requireVisible(long id,boolean lock){read();var rows=store.jdbc.queryForList("select r.record_id,r.code,r.name,r.status,r.version,r.data::text from plm_partner_record r join plm_sample_identity si on si.identity_id=r.record_id where r.kind='sample_identity' and r.deleted_flag=0 and r.record_id=? and "+visible("r")+(lock?" for update of r":""),id);require(rows.size()==1,"样品主码不存在或未获授权");return header(rows.get(0));}
 /** Validated source only; caller must never pass raw unvalidated request fields as source facts. */
 @Transactional public Map<String,Object> ensure(Map<String,Object> sample,Map<String,Object> input){
  write();var evidence=evidence(sample);String request=required(input.get("requestId"),"提交标识"),hash=PartnerQualityRules.digest(store.json,Map.of("input",input,"basis",evidence.basis())),eventKey="identity-request-"+UUID.nameUUIDFromBytes((store.access.actorId()+":"+request).getBytes(java.nio.charset.StandardCharsets.UTF_8));Long previous=store.created("sample_identity",request);if(previous!=null){var events=store.jdbc.queryForList("select data::text from plm_partner_event where record_id=? and request_id=?",previous,eventKey);require(events.size()==1&&hash.equals(text(decode(store.json,events.get(0).get("data")).get("requestHash"))),"同一提交标识已用于不同样品身份来源，请核对原结果");return requireVisible(previous,true);}
  long chosen=number(input.get("sampleIdentityId"));
  if(chosen>0){var h=requireVisible(chosen,true);SampleIdentityKeys.compatible(map(h.get("identityBasis")),evidence.basis());if(!text(h.get("identityKey")).equals(evidence.key()))required(input.get("identityReason"),"同一实物主码关联说明");return remember(h,request,eventKey,hash);}
  String key=evidence.exact()?evidence.key():"unclassified:"+store.access.actorId()+":"+required(input.get("requestId"),"提交标识");
  store.jdbc.queryForList("select pg_advisory_xact_lock(hashtextextended(?,0))","sample-identity:"+key);
  var found=store.jdbc.queryForList("select identity_id from plm_sample_identity where identity_key=?",key);
  if(!found.isEmpty()){var existing=requireVisible(number(found.get(0).get("identity_id")),true);SampleIdentityKeys.compatible(map(existing.get("identityBasis")),evidence.basis());return remember(existing,request,eventKey,hash);}
  long id=store.create("sample_identity",required(sample.get("name"),"样品类型名称"));var h=new LinkedHashMap<String,Object>();
  for(String field:List.of("name","specName","sourceType","sampleKind","sampleVersion","catalogStyleId","catalogStyleCode","catalogStyleLabel","supplierCode","supplierName","phoneModelId","phoneModelIds","phones","colorId","colorName","productId","modelProductId","projectId","purpose"))if(sample.containsKey(field))h.put(field,sample.get(field));
  var snapshot=map(sample.get("sourceSnapshot"));h.put("productName",text(snapshot.getOrDefault("productName",map(snapshot.get("product")).get("name"))));h.put("phoneName",phoneName(sample));h.put("domain",evidence.domain());h.put("identityKey",key);h.put("identityBasis",evidence.basis());h.put("status",evidence.exact()?"active":"needs_review");h.put("requiresReview",!evidence.exact());
  store.jdbc.update("insert into plm_sample_identity(identity_id,identity_key,source_type,basis) values(?,?,?,?::jsonb)",id,key,text(sample.get("sourceType")),encode(store.json,evidence.basis()));store.revision(id,h);store.save(id,h);store.event(id,"sample_identity_create",Map.of("identityBasis",evidence.basis(),"inventoryCreated",false),"identity-create-"+id);return remember(requireVisible(id,true),request,eventKey,hash);
 }
 private Map<String,Object> remember(Map<String,Object> h,String request,String eventKey,String hash){store.remember("sample_identity",request,number(h.get("id")));store.event(number(h.get("id")),"sample_identity_request",Map.of("requestHash",hash,"inventoryChanged",false),eventKey);return h;}
 private String phoneName(Map<String,Object> sample){var phones=maps(sample.get("phones"));if(phones.size()==1)return text(phones.get(0).getOrDefault("displayName",phones.get(0).get("modelName")));return text(map(map(sample.get("sourceSnapshot")).get("phone")).get("modelName"));}
 private SampleIdentityKeys.Evidence evidence(Map<String,Object> sample){
  var canonical=new LinkedHashMap<>(sample);
  // Existing commercial specs retain their exact CP link; changing entry points never changes the type.
  if(text(sample.get("sourceType")).equals("partner")&&number(sample.get("specId"))>0){var rows=store.jdbc.queryForList("select data::text from plm_partner_spec where spec_id=? and deleted_flag=0",sample.get("specId"));if(rows.size()==1){var spec=decode(store.json,rows.get(0).get("data"));for(String field:List.of("catalogStyleId","catalogSpecKey","catalogConfigurationKey","colorId","colorName"))if(spec.containsKey(field))canonical.put(field,spec.get(field));var phones=phoneIds(spec.get("phoneModelIds"));if(phones.size()==1)canonical.put("phoneModelId",phones.get(0));if(number(canonical.get("catalogStyleId"))==0){var technical=new LinkedHashMap<String,Object>();for(String f:List.of("specification","material","configuration","phoneModelIds","supplierColors"))if(spec.containsKey(f))technical.put(f,spec.get(f));technical.put("sampleVersion",text(sample.get("sampleVersion")));canonical.put("catalogConfigurationKey",PartnerQualityRules.digest(store.json,technical));}}}
  return SampleIdentityKeys.from(canonical);
 }
 public Map<String,Object> preview(Map<String,Object> sample,Map<String,Object> input){read();var evidence=evidence(sample);long selected=number(input.get("sampleIdentityId"));if(selected>0){var chosen=requireVisible(selected,false);SampleIdentityKeys.compatible(map(chosen.get("identityBasis")),evidence.basis());if(!text(chosen.get("identityKey")).equals(evidence.key()))required(input.get("identityReason"),"同一实物主码关联说明");return chosen;}if(evidence.exact()){var rows=store.jdbc.queryForList("select identity_id from plm_sample_identity where identity_key=?",evidence.key());if(!rows.isEmpty()){var existing=requireVisible(number(rows.get(0).get("identity_id")),false);SampleIdentityKeys.compatible(map(existing.get("identityBasis")),evidence.basis());return existing;}}return Map.of("sampleIdentityId",0L,"sampleCode","","requiresReview",!evidence.exact());}
 private String supplierName(Map<String,Object> data){String name=text(data.get("supplierName"));if(name.isEmpty())name=text(map(data.get("sourceSnapshot")).get("supplierName"));String code=text(data.get("supplierCode"));if(name.isEmpty()&&!code.isEmpty()){var names=store.jdbc.queryForList("select supplier_name from plm_supplier_profile where supplier_code=?",String.class,code);if(!names.isEmpty())name=names.get(0);}return name;}
 public void enrichBatch(Map<String,Object> batch){batch.put("supplierCode",text(batch.get("supplierCode")));batch.put("supplierName",supplierName(batch));var ids=store.jdbc.queryForList("select b.sample_identity_id,i.code from plm_partner_record b left join plm_partner_record i on i.record_id=b.sample_identity_id where b.kind='sample' and b.record_id=?",batch.get("id"));if(!ids.isEmpty()&&ids.get(0).get("sample_identity_id")!=null){batch.put("sampleIdentityId",ids.get(0).get("sample_identity_id"));batch.put("sampleCode",ids.get(0).get("code"));}}
 @Transactional public void attach(long batch,long identity,Map<String,Object> input){
  write();var h=requireVisible(identity,true);var b=store.load(batch,"sample",true);var current=store.jdbc.queryForObject("select sample_identity_id from plm_partner_record where record_id=?",Long.class,batch);require(current==null||current==identity,"原批次已关联其他主码，不能改写历史归属");
  if(current!=null)return;String reason=required(input.get("identityReason"),"批次关联主码原因");SampleIdentityKeys.compatible(map(h.get("identityBasis")),evidence(b).basis());store.jdbc.update("update plm_partner_record set sample_identity_id=? where record_id=? and sample_identity_id is null",identity,batch);
  store.event(identity,"sample_identity_batch",Map.of("batchId",batch,"reason",reason,"inventoryChanged",false),"identity-batch-"+batch);store.revision(identity,h);store.save(identity,h);
 }
 public List<Map<String,Object>> visibleBatches(long id,boolean lock){requireVisible(id,lock);var rows=store.jdbc.queryForList("select b.record_id as id,b.code,b.name,b.status,b.version,b.data::text from plm_partner_record b where b.kind='sample' and b.deleted_flag=0 and b.sample_identity_id=? and ("+store.access.visibleSqlClause("partner","b.record_id")+") order by b.record_id"+(lock?" for update of b":""),id);var out=new ArrayList<Map<String,Object>>();for(var row:rows){var d=decode(store.json,row.remove("data"));d.putAll(row);d.put("supplierCode",text(d.get("supplierCode")));d.put("supplierName",supplierName(d));d.put("sampleIdentityId",id);d.put("sampleCode",requireVisible(id,false).get("code"));d.put("balances",SampleLedger.replay(store.events(number(d.get("id")))).view());d.put("files",store.files(number(d.get("id"))));out.add(d);}return out;}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
 public Map<String,Object> detail(long id){var result=aggregate(id);new PartnerCatalogStyles(store).projectCurrent(List.of(result));return result;}
 private Map<String,Object> aggregate(long id){var h=requireVisible(id,false);if(number(h.get("redirectIdentityId"))>0){var target=aggregate(number(h.get("redirectIdentityId")));target.put("legacySampleCode",h.get("code"));target.put("redirectedFromIdentityId",id);return target;}var batches=visibleBatches(id,false);var totals=new LinkedHashMap<String,Object>();for(String key:List.of("onhand","available","retained","damaged","borrowed","inTransit"))totals.put(key,0L);var positions=new LinkedHashMap<String,Map<String,Object>>();var loans=new ArrayList<Map<String,Object>>();var files=new LinkedHashMap<Long,Map<String,Object>>();var visibleIds=new HashSet<Long>();
  for(var batch:batches){long bid=number(batch.get("id"));visibleIds.add(bid);var balances=map(batch.get("balances"));for(String key:totals.keySet())totals.put(key,add(number(totals.get(key)),number(balances.get(key))));for(var p:maps(balances.get("positions"))){String name=text(p.get("name"));if(name.isEmpty())continue;var aggregate=positions.computeIfAbsent(name,k->{var n=new LinkedHashMap<String,Object>();n.put("name",k);for(String f:List.of("good","retained","damaged","onhand","available"))n.put(f,0L);return n;});for(String f:List.of("good","retained","damaged","onhand","available"))aggregate.put(f,add(number(aggregate.get(f)),number(p.get(f))));}for(var loan:maps(balances.get("loans")))if(number(loan.get("outstanding"))>0){var l=new LinkedHashMap<>(loan);l.put("batchId",bid);l.put("batchCode",batch.get("code"));loans.add(l);}for(var file:maps(batch.get("files")))files.putIfAbsent(number(file.get("id")),file);}
  var active=positions.values().stream().filter(p->number(p.get("onhand"))!=0).toList();totals.put("positions",active);totals.put("loans",loans);h.put("balances",totals);h.put("positions",active);h.put("loans",loans);h.put("batches",batches);h.put("files",new ArrayList<>(files.values()));h.put("events",store.events(id).stream().filter(e->{var d=map(e.get("data"));return (!d.containsKey("batchId")||visibleIds.contains(number(d.get("batchId"))))&&maps(d.get("allocations")).stream().allMatch(a->visibleIds.contains(number(a.get("batchId"))));}).toList());return h;
 }
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
 public Map<String,Object> page(Map<String,String> query){read();var where="r.kind='sample_identity' and r.deleted_flag=0 and coalesce(r.data->>'redirectIdentityId','')='' and "+visible("r");var args=new ArrayList<Object>();String keyword=text(query.get("keyword")),domain=text(query.get("domain"));if(!keyword.isEmpty()){where+=" and (r.name ilike ? or r.code ilike ? or coalesce(r.data->>'specName','') ilike ? or coalesce(r.data->>'phoneName','') ilike ? or "+new PartnerCatalogStyles(store).currentNameSearch("r.data->>'catalogStyleId'")+")";for(int i=0;i<5;i++)args.add("%"+keyword+"%");}if(!domain.isEmpty()){SampleDomains.validate(domain);where+=" and r.data->>'domain'=?";args.add(domain);}long count=store.jdbc.queryForObject("select count(*) from plm_partner_record r where "+where,Long.class,args.toArray());long page=Math.max(1,number(query.getOrDefault("page","1"))),size=Math.min(100,Math.max(1,number(query.getOrDefault("size","50"))));args.add(size);args.add((page-1)*size);var rows=store.jdbc.queryForList("select r.record_id from plm_partner_record r where "+where+" order by r.updated_at desc,r.record_id desc limit ? offset ?",args.toArray());var content=rows.stream().map(r->aggregate(number(r.get("record_id")))).toList();new PartnerCatalogStyles(store).projectCurrent(content);return Map.of("content",content,"page",page,"size",size,"totalElements",count,"totalPages",(count+size-1)/size);}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
 public Map<String,Object> resolve(String code){read();require(text(code).matches("(?:SY|SP)-[0-9]{6,}"),"样品码格式无效");var rows=store.jdbc.queryForList("select record_id,kind,sample_identity_id from plm_partner_record where code=? and deleted_flag=0",text(code));require(rows.size()==1,"样品码不存在或未获授权");var r=rows.get(0);long id=number(r.get("record_id"));if(text(r.get("kind")).equals("sample_identity")){var identity=detail(id);var result=new LinkedHashMap<String,Object>();result.put("type","identity");result.put("sampleIdentityId",identity.get("id"));result.put("sampleCode",identity.get("code"));result.put("identity",identity);if(number(identity.get("id"))!=id)result.put("legacySampleCode",code);return result;}store.access.requirePartner(id);var result=new LinkedHashMap<String,Object>();result.put("type","legacy_batch");result.put("batchId",id);result.put("batchCode",code);if(r.get("sample_identity_id")!=null){long identity=number(r.get("sample_identity_id"));result.put("sampleIdentityId",identity);result.put("sampleCode",requireVisible(identity,false).get("code"));result.put("identity",detail(identity));}return result;}
 /** Head IDs are locked in ascending order before the SP lock, matching aggregate/shipment actions. */
 public long lockSourceResolution(long batch,Map<String,Object> input,Map<String,Object> source){store.access.requirePartner(batch);Long old=store.jdbc.queryForObject("select sample_identity_id from plm_partner_record where record_id=? and kind='sample'",Long.class,batch);var ids=new TreeSet<Long>();if(old!=null)ids.add(old);if(source!=null){var evidence=evidence(source);if(evidence.exact()){store.jdbc.queryForList("select pg_advisory_xact_lock(hashtextextended(?,0))","sample-identity:"+evidence.key());for(var existing:store.jdbc.queryForList("select identity_id from plm_sample_identity where identity_key=?",evidence.key()))ids.add(number(existing.get("identity_id")));}}long target=number(input.get("mergeTargetIdentityId"));if(target>0)ids.add(target);for(long id:ids)requireVisible(id,true);return old==null?0:old;}
 public void sourceResolved(long batch,long expectedIdentity,Map<String,Object> source,Map<String,Object> input){
  Long current=store.jdbc.queryForObject("select sample_identity_id from plm_partner_record where record_id=?",Long.class,batch);require((current==null?0:current)==expectedIdentity,"样品主码关联已变化，请刷新后重试");var evidence=evidence(source);
  if(current==null){var command=new LinkedHashMap<>(input);command.put("identityReason",required(input.get("reason"),"来源补齐原因"));var head=ensure(source,command);attach(batch,number(head.get("id")),command);return;}
  var old=requireVisible(current,true);String oldKey=text(old.get("identityKey"));if(!oldKey.startsWith("unclassified:")){SampleIdentityKeys.compatible(map(old.get("identityBasis")),evidence.basis());return;}
  require(evidence.exact(),"实际来源仍未形成唯一型号、颜色或版本身份；请补齐来源或明确选已有主码");
  store.jdbc.queryForList("select pg_advisory_xact_lock(hashtextextended(?,0))","sample-identity:"+evidence.key());var other=store.jdbc.queryForList("select identity_id from plm_sample_identity where identity_key=?",evidence.key());long target=number(input.get("mergeTargetIdentityId"));
  if(!other.isEmpty()&&number(other.get(0).get("identity_id"))!=current){long actual=number(other.get(0).get("identity_id"));require(target==actual&&Boolean.TRUE.equals(input.get("confirmSameType")),"此来源已有样品主码（ID "+actual+"）；请明确选择该目标、确认同种实物并填写并码原因，不能自动合并");var destination=requireVisible(target,true);SampleIdentityKeys.compatible(map(destination.get("identityBasis")),evidence.basis());String reason=required(input.get("identityReason"),"同种实物并码原因");
   store.jdbc.update("update plm_partner_record set sample_identity_id=? where record_id=? and sample_identity_id=?",target,batch,current);old.put("redirectIdentityId",target);old.put("status","superseded");store.event(current,"sample_identity_redirect",Map.of("batchId",batch,"targetIdentityId",target,"reason",reason,"inventoryChanged",false),"redirect-"+UUID.nameUUIDFromBytes((batch+":"+input.get("requestId")).getBytes(java.nio.charset.StandardCharsets.UTF_8)));store.revision(current,old);store.save(current,old);return;
  }
  require(target==0||target==current,"目标主码与实际来源不一致");store.jdbc.update("update plm_sample_identity set identity_key=?,source_type=?,basis=?::jsonb where identity_id=?",evidence.key(),text(source.get("sourceType")),encode(store.json,evidence.basis()),current);
  old.put("identityKey",evidence.key());old.put("identityBasis",evidence.basis());old.put("requiresReview",false);old.put("domain",evidence.domain());old.put("status","active");for(String field:List.of("sourceType","name","specName","catalogStyleId","catalogStyleCode","supplierCode","supplierName","phoneModelId","phones","phoneModelIds","colorId","colorName","sampleKind","sampleVersion","modelProductId","productId","projectId"))if(source.containsKey(field))old.put(field,source.get(field));old.put("phoneName",phoneName(source));store.revision(current,old);store.save(current,old);store.event(current,"sample_identity_source",Map.of("batchId",batch,"reason",required(input.get("reason"),"来源补齐原因"),"inventoryChanged",false),"source-"+UUID.nameUUIDFromBytes((batch+":"+input.get("requestId")).getBytes(java.nio.charset.StandardCharsets.UTF_8)));
 }
 public Map<String,Object> candidates(Map<String,Object> source,Map<String,Object> input){var exact=preview(source,input);return Map.of("content",number(exact.get("sampleIdentityId"))>0?List.of(exact):List.of(),"canCreate",true,"requiresReview",Boolean.TRUE.equals(exact.get("requiresReview")),"reason",Boolean.TRUE.equals(exact.get("requiresReview"))?"来源未形成唯一实物身份，不按名称合并；可明确选择已有主码或为本次实物建立待核对主码":"仅按真实来源身份匹配，不按名称合并");}
}
